def wait_circular(prices):
    n = len(prices)
    out = [0] * n
    waiting = []
    for k in range(2 * n):
        i = k % n
        while waiting and prices[waiting[-1]] < prices[i]:
            j = waiting.pop()
            out[j] = (i - j) % n
        if k < n:
            waiting.append(i)
    return out

