def running_kth(a, k):
    keep, out = [], []   # the k smallest so far, as a max-heap (negated)
    for v in a:
        heapq.heappush(keep, -v)
        if len(keep) > k:
            heapq.heappop(keep)
        out.append(-keep[0] if len(keep) == k else None)
    return out

